"""Census-based name sampler for Concordia persona generation.

Uses 2020 U.S. Census Bureau frequency data (top 1000 first/last names)
to sample realistic names weighted by race/ethnicity frequency counts.
This replaces LLM-generated names entirely.

Data source:
https://www.census.gov/topics/population/genealogy/data/2020_names.html

Usage:
  sampler = CensusNameSampler(seed=42)
  name = sampler.sample_full_name(
      ethnicity='Native American',
      gender='woman',
      used_names=set(),
  )
  # => 'Jennifer Begay'
"""

import random
from typing import Any, Dict, List, Optional, Set, Tuple

