# Ethnicity keys used in the frequency dicts above.
_ETHNICITY_KEYS = [
    'White American',
    'Black American',
    'Native American',
    'East Asian American',
    'South Asian American',
    'Pacific Islander',
    'Mixed/Multiracial',
    'Latino/Hispanic',
    'Middle Eastern American',
]


class CensusNameSampler:
  """Samples names from census frequency distributions by ethnicity."""

  def __init__(self, seed: int = 42):
    self._rng = random.Random(seed)

    # Build weighted distributions per ethnicity
    self._first_by_eth_male: Dict[str, List[Tuple[str, int]]] = {}
    self._first_by_eth_female: Dict[str, List[Tuple[str, int]]] = {}
    self._last_by_eth: Dict[str, List[Tuple[str, int]]] = {}

    for ethnicity in _ETHNICITY_KEYS:
      self._first_by_eth_male[ethnicity] = [
          (name, counts.get(ethnicity, 0))
          for name, counts in _FIRST_NAMES_MALE
          if counts.get(ethnicity, 0) > 0
      ]
      self._first_by_eth_female[ethnicity] = [
          (name, counts.get(ethnicity, 0))
          for name, counts in _FIRST_NAMES_FEMALE
          if counts.get(ethnicity, 0) > 0
      ]
      self._last_by_eth[ethnicity] = [
          (name, counts.get(ethnicity, 0))
          for name, counts in _LAST_NAMES
          if counts.get(ethnicity, 0) > 0
      ]

    # The census groups East Asian, South Asian, and Pacific Islander under
    # one 'Asian/Pacific Islander' category, giving identical weights to
    # surnames like 'Liu' (Chinese) for South Asian agents. Fix this by
    # filtering surnames to their actual ethnic origin.
    _EAST_ASIAN_ONLY = frozenset({  # pylint: disable=invalid-name
        'Wang',
        'Li',
        'Zhang',
        'Liu',
        'Chen',
        'Yang',
        'Huang',
        'Wu',
        'Zhou',
        'Xu',
        'Lin',
        'Sun',
        'Ma',
        'Zhu',
        'Hu',
        'Guo',
        'Luo',
        'He',
        'Liang',
        'Zheng',
        'Xie',
        'Song',
        'Tang',
        'Han',
        'Deng',
        'Feng',
        'Cao',
        'Xiao',
        'Pan',
        'Cheng',
        'Ye',
        'Lu',
        'Wei',
        'Jiang',
        'Tian',
        'Du',
        'Ding',
        'Shen',
        'Fan',
        'Wan',
        'Mao',
        'Choi',
        'Yoon',
        'Jang',
        'Yoo',
        'Cho',
        'Shin',
        'Kwon',
        'Ahn',
        'Seo',
        'Hong',
        'Ko',
        'Moon',
        'Son',
        'Bae',
        'Hwang',
        'Ryu',
        'Nguyen',
        'Tran',
        'Le',
        'Pham',
        'Hoang',
        'Phan',
        'Vu',
        'Dang',
        'Bui',
        'Do',
        'Ngo',
        'Duong',
        'Ly',
        'Vo',
        'Huynh',
        'Tanaka',
        'Suzuki',
        'Sato',
        'Watanabe',
        'Takahashi',
        'Yamamoto',
        'Nakamura',
        'Kobayashi',
        'Ito',
        'Saito',
        'Kim',
        'Lee',
        'Park',
        'Jung',
        'Kang',
        'Chang',
        'Hsu',
        'Tsai',
        'Lai',
        'Chien',
    })
    _SOUTH_ASIAN_ONLY = frozenset({  # pylint: disable=invalid-name
        'Patel',
        'Shah',
        'Kumar',
        'Singh',
        'Sharma',
        'Gupta',
        'Mehta',
        'Joshi',
        'Desai',
        'Reddy',
        'Nair',
        'Rao',
        'Menon',
        'Iyer',
        'Bhat',
        'Pillai',
        'Srinivasan',
        'Krishnamurthy',
        'Agarwal',
        'Khan',
        'Ahmed',
        'Ali',
        'Hussain',
        'Rahman',
        'Islam',
        'Das',
        'Mukherjee',
        'Banerjee',
        'Chatterjee',
        'Ghosh',
        'Chowdhury',
        'Roy',
        'Sen',
        'Dey',
        'Biswas',
        'Fernando',
        'Perera',
        'Jayawardena',
        'Wickramasinghe',
        'Thapa',
        'Tamang',
        'Gurung',
        'Shrestha',
    })

    # Filter: remove East-Asian-only surnames from South Asian/PI pools
    for eth in ('South Asian American', 'Pacific Islander'):
      if eth in self._last_by_eth:
        self._last_by_eth[eth] = [
            (n, w)
            for n, w in self._last_by_eth[eth]
            if n not in _EAST_ASIAN_ONLY
        ]
    # Filter: remove South-Asian-only surnames from East Asian/PI pools
    for eth in ('East Asian American', 'Pacific Islander'):
      if eth in self._last_by_eth:
        self._last_by_eth[eth] = [
            (n, w)
            for n, w in self._last_by_eth[eth]
            if n not in _SOUTH_ASIAN_ONLY
        ]

  def _weighted_sample(
      self,
      pool: List[Tuple[str, int]],
  ) -> str:
    """Sample a name from a weighted pool."""
    if not pool:
      return 'Alex'
    names, weights = zip(*pool)
    return self._rng.choices(names, weights=weights, k=1)[0]

  def sample_first_name(
      self,
      ethnicity: str,
      gender: Optional[str] = None,
  ) -> str:
    """Sample a first name weighted by census frequency for this ethnicity."""
    if gender == 'woman' or gender == 'female':
      pool = self._first_by_eth_female.get(ethnicity)
    elif gender == 'man' or gender == 'male':
      pool = self._first_by_eth_male.get(ethnicity)
    else:
      # Fallback or non-binary: use combined or random choice from either
      # Putting unclassified in both means both pools are large.
      # Let's just use female pool as default or combine them.
      # For simplicity, let's use male pool if gender not specified or unknown.
      pool = self._first_by_eth_male.get(ethnicity)

    if not pool:
      # Fallback to White American if ethnicity not found
      if gender == 'woman' or gender == 'female':
        pool = self._first_by_eth_female.get('White American', [])
      else:
        pool = self._first_by_eth_male.get('White American', [])

    return self._weighted_sample(pool)

  def sample_last_name(
      self,
      ethnicity: str,
  ) -> str:
    """Sample a last name weighted by census frequency for this ethnicity."""
    pool = self._last_by_eth.get(ethnicity)
    if not pool:
      pool = self._last_by_eth.get('White American', [])
    return self._weighted_sample(pool)

  def sample_full_name(
      self,
      ethnicity: str,
      gender: Optional[str] = None,
      used_names: Optional[Set[str]] = None,
      max_attempts: int = 100,
  ) -> str:
    """Sample a unique full name for the given ethnicity.

    Args:
      ethnicity: Agent ethnicity (e.g. 'Native American', 'Black American').
      gender: Used for filtering first names.
      used_names: Set of names already assigned; guarantees uniqueness.
      max_attempts: Max retries before appending a disambiguator.

    Returns:
      A unique full name like 'Jennifer Begay' or 'Marcus Washington'.
    """
    if used_names is None:
      used_names = set()

    first = self.sample_first_name(ethnicity, gender)
    last = self.sample_last_name(ethnicity)

    for _ in range(max_attempts):
      first = self.sample_first_name(ethnicity, gender)
      last = self.sample_last_name(ethnicity)
      full = f'{first} {last}'
      if full not in used_names:
        return full

    # Extremely rare: add middle initial to disambiguate
    initial = self._rng.choice('ABCDEFGHJKLMNPRSTW')
    return f'{first} {initial}. {last}'

  def sample_population(
      self,
      agents: List[Dict[str, Any]],
  ) -> None:
    """Assign names to a list of agent dicts in-place.

    Each agent dict must have 'ethnicity' and optionally 'gender'.
    Sets agent['name'] to a unique census-sampled name.

    Args:
      agents: List of agent dicts, each with 'ethnicity' and optionally
        'gender' keys.
    """
    used = set()
    for agent in agents:
      ethnicity = agent.get('ethnicity', 'White American')
      gender = agent.get('gender')
      name = self.sample_full_name(
          ethnicity=ethnicity,
          gender=gender,
          used_names=used,
      )
      agent['name'] = name
      used.add(name)
